// MEIP Regex & NLP Skill Extraction Engine for Moroccan Tech Stack
const TECH_TAXONOMY = [
  'React', 'TypeScript', 'Node.js', 'Python', 'Pandas', 'PostgreSQL',
  'Supabase', 'TailwindCSS', 'Docker', 'Kubernetes', 'FastAPI', 'Spring Boot',
  'Java', 'PHP', 'Laravel', 'Angular', 'Vue.js', 'Next.js', 'AWS', 'GCP',
  'SQL', 'NoSQL', 'MongoDB', 'Redis', 'CI/CD', 'Git', 'Tableau', 'Scrum'
];

const items = $input.all();
const results = [];

for (const item of items) {
  const id = item.json.id;
  const text = `${item.json.title || ''} ${item.json.company || ''}`.toLowerCase();

  const extractedSkills = [];
  for (const tech of TECH_TAXONOMY) {
    const pattern = new RegExp(`\\b${tech.replace(/\./g, '\\.')}\\b`, 'i');
    if (pattern.test(text)) {
      extractedSkills.push(tech);
    }
  }

  // Default skill tag fallback if none detected
  if (extractedSkills.length === 0) {
    if (text.includes('data') || text.includes('analytic')) extractedSkills.push('Python', 'SQL');
    else if (text.includes('fullstack') || text.includes('web')) extractedSkills.push('React', 'Node.js');
    else extractedSkills.push('Software Engineering');
  }

  results.push({
    json: {
      job_id: id,
      extracted_skills: JSON.stringify(extractedSkills)
    }
  });
}

return results;

